WITH cleaned AS (SELECT *, CASE WHEN country = 'TH' THEN 1 ELSE 0 END AS is_th FROM sessions WHERE customer_id IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, MAX(session_start_flag) FILTER (WHERE country = 'SG') AS sg_max_session_start_flag, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min FROM sessions_sessions GROUP BY 1 HAVING MAX(session_start_flag) FILTER (WHERE country = 'SG') < 0
